import{_ as o,l,o as e,c as n,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"债务可持续与 r − g","description":"","frontmatter":{"title":"债务可持续与 r − g","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/debt-sustainability.md","filePath":"econ/debt-sustainability.md","lastUpdated":1789023840000}'),c={name:"econ/debt-sustainability.md"};function E(_,a,g,m,A,b){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="债务可持续与-r-−-g" tabindex="-1">债务可持续与 r − g <a class="header-anchor" href="#债务可持续与-r-−-g" aria-label="Permalink to &quot;债务可持续与 r − g&quot;">​</a></h1><div class="epigraph"><p>一次总付世界里，债务比率的运动由 $(r-g)$ 与初级赤字决定；这是会计，不是免费午餐的证明。</p><footer>—— 公共债务会计；Blanchard, Public Debt and Low Interest Rates, AER 2019；对照 Bohn 的可持续检验</footer></div><p><a href="/econ/arellano-sovereign">上一课</a>的新兴市场被违约期权钉住。发达经济多年低 \\(r\\)、少违约，争论换成 <strong>\\(r-g\\)</strong>。本课缺口是把会计接到已有的内生 \\(r\\)（Aiyagari、GK、全球周期），而不是口号。不重校准阿根廷利差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\Delta b_t \\approx (r_t-g_t)b_{t-1}-s_t\\)， \\(s\\) 为初级盈余/GDP。若 \\(r\\lt g\\)，即使 \\(s=0\\)，比率也可降。Blanchard：低利率下公共债的财政成本与挤出可能小于过去教科书。但 \\(r\\) 含期限溢价与违约/通胀风险，不是外生安全利率；一旦债高，\\(r\\) 可升（Arellano 的连续）。缺口是：可持续是会计加反应函数，不是 \\(r\\lt g\\) 的历史平均值本身。</p><p><span class="marginnote">Blanchard, <em>AER</em> 2019。Bohn, <em>QJE</em> 1998：盈余对债的反应。Reis 对 \\(r-g\\) 的讨论。私人 \\(r\\gt g\\) 与公共 \\(r-g\\) 不是同一 \\(r\\)（上一单元 Piketty 课已警告）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>会计：名义与实际、外币与本币要分。滚动：平均期限决定对利率跳升的暴露。Bohn：可持续需要 \\(s\\) 对 \\(b\\) 的正反应（在一定条件下）。模型：把政府预算接进 NK 或 HANK，货币规则与财政规则谁钉住价格水平——下一课主导。低 \\(r\\) 的来源：储蓄过剩、安全资产需求、增长下降，各有不同的反事实。</p>',8)),(e(),s(h,null,{default:t(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%CE%94b%20%E2%89%88%20(r-g)b%20-%20s%22%5D%20--%3E%20PATH%5B%22%E5%80%BA%E8%B7%AF%E5%BE%84%22%5D%0A%20%20R%5B%22%E5%86%85%E7%94%9F%20r%22%5D%20--%3E%20ACC%0A%20%20S%5B%22%E5%88%9D%E7%BA%A7%E7%9B%88%E4%BD%99%E8%A7%84%E5%88%99%22%5D%20--%3E%20ACC%0A%20%20JUMP%5B%22r%20%E8%B7%B3%E5%8D%87%20%2F%20%E5%86%8D%E8%9E%8D%E8%B5%84%22%5D%20--%3E%20RISK%5B%22%E6%BB%9A%E5%8A%A8%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 HANK：公债是流动性资产，供给 \\(b\\) 改贫流动性份额与 \\(r\\)；可持续与稳定器互相缠。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是滚动。短债把 \\(r\\) 的实现立刻送进会计；长债把重估送进债权人净值（GK、全球周期）。\\(r\\lt g\\) 的样本若来自被压抑的安全利率，财政扩张本身可以结束它。通胀：名义 \\(r\\) 与增长名义 \\(g\\) 的差含稀释，那是铸币税，不是增长礼物——主导课展开。</p><p>Piketty 的私人 \\(r\\gt g\\) 抬私人财富；公共 \\(r\\lt g\\) 降公共债比率：可并存，因为风险与流动性不同。不要用同一个字母取消两课。</p><p><span class="marginnote">本课不预测某国债上限的百分点。 Reinhart–Rogoff 的门槛争论是经验，不是本课的会计。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优债的 Ramsey 全套。违约仍是新兴市场的硬约束。下一课：会计还要问是财政还是货币在钉价格。银行危机史用另一套事实。</p><p>后课默认：\\(r-g\\) 是会计；可持续要 \\(s\\) 的反应与内生 \\(r\\)。下一课：财政主导 vs 货币主导。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>债比率会计由 \\(r-g\\) 与初级盈余驱动。</li><li>\\(r\\lt g\\) 的历史不是外生许可证；\\(r\\) 随债与体制变。</li><li>公共 \\(r\\) 与私人财富的 \\(r\\) 不是同一个对象。</li><li>出处：Blanchard, <em>AER</em> 2019；Bohn, <em>QJE</em> 1998。</li></ul>',10))])}const f=o(c,[["render",E]]);export{u as __pageData,f as default};
